import type { Message } from "../i18n";
import type { MessageKey } from "../i18n/en";
import type { ViewPreset } from "../state/store";
import type { IonSource } from "./flight";
import type { SliceState } from "./pa";

/**
 * Template gallery. The geometry of each template is generated by the native core
 * (src-tauri/src/templates.rs, `create_template`) as a small .pa#; this file holds what the UI
 * applies once it is refined: electrode names, voltages, a ready-to-fly ion source and a view.
 */

export type TemplateId = "einzel" | "quadrupole" | "reflectron" | "trap";

export interface TemplateDef {
  id: TemplateId;
  titleKey: MessageKey;
  descKey: MessageKey;
  /** Default electrode names, by electrode number. */
  roles: Record<number, Message>;
  voltages: Record<number, number>;
  source: Partial<IonSource>;
  /** Section plane to start with (default: the array's own). */
  slice?: Partial<SliceState>;
  view: ViewPreset;
}

const ring = (n: number): Message => ({ key: "electrode.ring", params: { n } });

export const TEMPLATES: readonly TemplateDef[] = [
  {
    id: "einzel",
    titleKey: "template.einzel.title",
    descKey: "template.einzel.desc",
    roles: { 1: { key: "electrode.entrance" }, 2: { key: "electrode.focus" }, 3: { key: "electrode.exit" } },
    voltages: { 1: 0, 2: 80, 3: 0 },
    source: { count: 40, massAmu: 100, chargeE: 1, energyEv: 100, position: [1, 0, 0], shape: "line", widthMm: 14, coneDeg: 0 },
    view: "front",
  },
  {
    id: "quadrupole",
    titleKey: "template.quadrupole.title",
    descKey: "template.quadrupole.desc",
    roles: { 1: { key: "electrode.rodsY" }, 2: { key: "electrode.rodsZ" }, 3: { key: "electrode.endPlates" } },
    voltages: { 1: 2.5, 2: -2.5, 3: 0 },
    source: { count: 120, massAmu: 100, chargeE: 1, energyEv: 100, position: [1, 0, 0], shape: "disk", widthMm: 6, coneDeg: 0 },
    // Cross-section through the middle of the rods (x = 30 mm): the four poles and their field.
    slice: { axis: 0, coord: 60 },
    view: "iso",
  },
  {
    id: "reflectron",
    titleKey: "template.reflectron.title",
    descKey: "template.reflectron.desc",
    roles: { 1: { key: "electrode.entranceRing" }, 2: ring(1), 3: ring(2), 4: ring(3), 5: ring(4), 6: ring(5), 7: { key: "electrode.backPlate" } },
    voltages: { 1: 0, 2: 25, 3: 50, 4: 75, 5: 100, 6: 125, 7: 150 },
    source: { count: 30, massAmu: 100, chargeE: 1, energyEv: 100, position: [1, 0, 0], elevationDeg: 3, shape: "point", coneDeg: 1 },
    view: "front",
  },
  {
    id: "trap",
    titleKey: "template.trap.title",
    descKey: "template.trap.desc",
    roles: { 1: { key: "electrode.trapRing" }, 2: { key: "electrode.endCaps" } },
    voltages: { 1: 9, 2: 0 },
    source: { count: 40, massAmu: 100, chargeE: 1, energyEv: 5, position: [1, 0, 0], shape: "line", widthMm: 3, coneDeg: 0 },
    view: "front",
  },
];

export function templateById(id: TemplateId): TemplateDef {
  return TEMPLATES.find((t) => t.id === id)!;
}
